import React from 'react';import {createRoot} from 'react-dom/client';import {openDB} from 'idb';
import {StudyRepository,STUDY_STORES} from '../../src/features/study/StudyRepository';import StudySetView from '../../src/features/study/components/StudySetView';import {LanguageProvider} from '../../src/lib/LanguageContext';import ConfirmDialogHost from '../../src/components/ConfirmDialog';
const owner='00000000-0000-4000-8000-000000000001',entry='00000000-0000-4000-8000-000000000010',other='00000000-0000-4000-8000-000000000020';
const db=await openDB('private-official-browser',1,{upgrade(db){for(const name of STUDY_STORES){const s=db.createObjectStore(name,{keyPath:'id'});if(['study_cards','study_states','study_events'].includes(name)){s.createIndex('deck','deck_id');if(name==='study_events')s.createIndex('deck_day',['deck_id','local_day']);}}}});
const repository=new StudyRepository(db,()=>owner,'browser'),page={id:'deck',workspace_owner_id:owner,title:'Official',kind:'study_set',study_items:[],official_pack_id:'gsat-1-2'};window.studyDb=db;window.studyRepo=repository;
if(!await db.get('study_settings','deck')){
 await repository.ensureDeck({...page,official_pack_id:undefined});const [card]=await repository.addCards('deck',[{front:'apple',back:'蘋果',dictionary_entry_id:entry}]);
 const session=await repository.startSession('deck','scheduled');const next=await repository.presentScheduled(session.id);await repository.rateSession({sessionId:session.id,cardId:card.id,revision:next.session.revision,contentRevision:card.content_revision,expectedHead:next.snapshot.states[0].head,rating:4,actionId:crypto.randomUUID(),now:Date.now()});
 await db.put('study_cards',{...await db.get('study_cards',card.id),official_pack_id:'gsat-1-2',official_source_entry_id:entry});await db.put('study_settings',{...await db.get('study_settings','deck'),official_pack_id:'gsat-1-2'});localStorage.setItem('fixture-link',entry);
}
window.calls=[];const detail=id=>({entry:{id,kind:'word',headword:id===entry?'apple':'book',status:'published'},senses:[{id:'sense-'+id,entry_id:id,part_of_speech:'noun',gloss_zh_tw:id===entry?'蘋果':'書'}],relations:[],related:[],inflections:[],etymologies:[],learning_notes:[],examples:[],lexical_annotations:[]});
window.dictionaryClient={auth:{getUser:async()=>({data:{user:{id:owner}}}),onAuthStateChange:()=>({data:{subscription:{unsubscribe(){}}}})},from:()=>({select(){return this;},eq(){return this;},maybeSingle:async()=>({data:localStorage.getItem('fixture-link')?{dictionary_entry_id:localStorage.getItem('fixture-link')}:null})}),rpc:async(name,args={})=>{window.calls.push({name,args});if(name==='official_private_card_capabilities')return new URLSearchParams(location.search).has('legacy')?{error:{code:'42883'}}:{data:{version:1}};if(name==='pull_study_changes')return {data:[]};if(name==='apply_study_operation'||name==='apply_study_resolution')return {data:true};if(name==='set_study_dictionary_link'){if(args.word_uuid)localStorage.setItem('fixture-link',args.word_uuid);else localStorage.removeItem('fixture-link');return {data:null};}if(name==='search_published_dictionary')return {data:{items:[detail(other).entry],page:0,total:1,has_more:false}};if(name==='get_published_dictionary_entry')return {data:detail(args.entry_uuid)};return {error:{message:'Unexpected fixture '+name}};}};
createRoot(document.getElementById('root')).render(<LanguageProvider initialLanguage="zh-TW"><StudySetView page={page} repository={repository} onTitleChange={()=>{}}/><ConfirmDialogHost/></LanguageProvider>);
